"""Behavior: note.archive

Archives a note for a signed in member.
"""

from kernel import AppError, require_session


def _validate_note_id(note_id):
    if not note_id or not isinstance(note_id, str):
        raise AppError("INVALID_PARAMETER")


def _load_note(store, note_id):
    note = store.note(note_id)
    if note is None:
        raise AppError("NOT_FOUND")
    return note


def _ensure_not_archived(note):
    if note.get("archived"):
        raise AppError("ALREADY_ARCHIVED")


def _shape_output(note):
    return {
        "id": note["id"],
        "title": note.get("title"),
        "archived": note["archived"],
    }


def archive_note(store, session, note_id=None):
    require_session(session)
    _validate_note_id(note_id)

    note = _load_note(store, note_id)
    _ensure_not_archived(note)

    note["archived"] = True
    saved = store.save_note(note)

    return _shape_output(saved)
